Lemma round fx R p :
  getr R (reg 2) = Z_to_bv 64 sp -> getr R (reg 10) = Z_to_bv 64 b -> getr R (reg 11) = Z_to_bv 64 p -> getr R (reg 13) = Z_to_bv 64 24 ->
  b + 24 <= p -> p <= 140737488355328 ->
  exists fx' R', (forall x, In x KSL -> getr R' (reg x) = getr R (reg x)) /\
    (   (msteps RSEGS (st fx R 0x39538 M) (st fx' R' 0x39538 M) /\ getr R' (reg 11) = Z_to_bv 64 (p - 24) /\ p - 24 <> b)
     \/ (msteps RSEGS (st fx R 0x39538 M) (st fx' R' 0x39548 M) /\ p - 24 = b)).
Proof.
