Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PECKU.klayout_U L LY.

(* [comment removed for export] *)
Definition estk_dtor_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBr : list (Z * Z)) (cr : credit) (t ov fb sp r : Z) (en : PEC.enc),
    hi_heap HI (PEC.enc_own en ++ LBr) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> PMSP.entry AD L R M sp r 0 ->
    getr R 10%bv = Z_to_bv 64 t -> sp <= t -> t + 8 <= hl_sptop L -> L5.u64_at RSEGS M t (ov + 24) ->
    sp <= ov -> ov + 56 <= hl_sptop L -> ov mod 8 = 0 -> PEC.enc_at RSEGS EE L PMSP.T3 PMSP.T4 M ov fb en ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model),
        regs_preserved R R' ->
        L5C.hpres L LBr sp (PMSP.pm_scr 0) [(ov + 24, 24)] M M' ->
        model_but_vm model model' -> hi_heap HI LBr cr M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R 0x39514 M model) K.

(* [comment removed for export] *)
Lemma hpres_refl LB sp scr W M : L5C.stk (hl_sptop L) M sp scr -> 0 <= scr -> (forall b, In b LB -> fst b + snd b <= hl_ceil L) -> L5C.hpres L LB sp scr W M M.
Proof.
