(* [comment removed for export] *)
Definition sink_dtor_spec (P : PESK.sink_policy) : Prop :=
  PESK.sp_mode P ->
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBr : list (Z * Z)) (cr : credit) (t o sp r : Z) (k : PESK.sink),
    hi_heap HI (PESK.sink_own k ++ LBr) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> PMSP.entry AD L R M sp r 0 ->
    getr R 10%bv = Z_to_bv 64 t -> sp <= t -> t + 8 <= hl_sptop L -> L5.u64_at RSEGS M t o ->
    sp <= o -> o + 24 <= hl_sptop L -> o mod 8 = 0 -> PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P M o k ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model),
        regs_preserved R R' ->
        L5C.hpres L LBr sp (PMSP.pm_scr 0) [(o, 24)] M M' ->
        model_but_vm model model' ->
        hi_heap HI LBr (if PESK.sk_c k =? 0 then cr else (fst cr + 1, snd cr + PESK.sp_csz P (PESK.sk_c k))) M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R 0x35960 M model) K.

